/* =====================================================================
   Banco de preguntas · Física 3 · S01 · Imanes, campo magnético y líneas de campo
   100 plantillas parametrizadas, todas propias (source: 'propia').
   B de la Tierra ≈ 50 µT = 0.50 G; 1 T = 10⁴ G; 1 mT = 10³ µT. concept: true = conceptual.
   Cada numérica trae oracle(v, LM): la misma respuesta recalculada con
   LabMath.magnet por otro camino (lo comprueba scripts/labs-math/magnetic-field-map.js).
   ===================================================================== */
(function () {
  var K = window.CBBankKit('f3', '01');
  var DEG = 180 / Math.PI;
  var SCI = ' Responde con notación científica.';
  function fx(v, d) { return Number(v.toFixed(d == null ? 2 : d)).toString(); }
  var MG = function (LM) { return LM.magnet; };

  // La respuesta y cada error típico difieren al menos 3 % (mensajes «casi» sin ambigüedad).
  function distinct(q) {
    return function (v) {
      if (q.baseWhere && !q.baseWhere(v)) return false;
      var vals = [q.answer(v)].concat(Object.keys(q.mistakes).map(function (k) { return q.mistakes[k](v); }));
      for (var i = 0; i < vals.length; i++) for (var j = i + 1; j < vals.length; j++) {
        var big = Math.max(Math.abs(vals[i]), Math.abs(vals[j]));
        if (Math.abs(vals[i] - vals[j]) <= 0.03 * (big >= 0.05 ? Math.max(big, 0.5) : big)) return false;
      }
      return true;
    };
  }
  // Numérica con oráculo independiente.
  function N(id, sub, d, vars, prompt, answer, why, o, oracle) {
    o = o || {};
    var q = K.N(id, sub, d, vars, prompt, answer, why, o);
    if (o.mistakes) { q.baseWhere = o.where; q.where = distinct(q); }
    q.oracle = oracle;
    return q;
  }
  var C = K.C;
  // Campo total de dos componentes perpendiculares (este y norte), en la unidad que se dé.
  function perp(LM, e, n) { return MG(LM).combine([{ mag: e, bearing: 90 }, { mag: n, bearing: 0 }]); }

  var Q = [
    /* ======================= Polos y fuerza entre imanes ======================= */
    C('po-iguales', 'polos', 1, 'Dos imanes de barra se enfrentan con sus polos N. ¿Qué ocurre?', 'Se repelen',
      [['Se atraen', 'Se atraen los polos distintos (N con S), no los iguales.'], ['No hay fuerza entre ellos', 'Los imanes interactúan sin tocarse, por medio del campo magnético.'], ['Se atraen primero y luego se repelen', 'La fuerza entre polos iguales es siempre de repulsión.']],
      'Polos iguales se repelen.'),
    C('po-opuestos', 'polos', 1, 'Acercas el polo N de un imán al polo S de otro. ¿Qué ocurre?', 'Se atraen',
      [['Se repelen', 'Se repelen los polos iguales, no los distintos.'], ['Se neutralizan y pierden el magnetismo', 'Un imán no pierde su magnetismo por acercarse a otro.'], ['No pasa nada hasta que se tocan', 'La fuerza actúa a distancia, a través del campo.']],
      'Polos distintos se atraen.'),
    C('po-partir', 'polos', 1, 'Partes un imán de barra por la mitad. ¿Qué obtienes?', 'Dos imanes, cada uno con su polo N y su polo S',
      [['Un trozo con polo N y otro con polo S', 'No existen polos sueltos: en el corte aparecen un N y un S nuevos.'], ['Dos trozos sin magnetismo', 'Cada pedazo sigue siendo un imán, aunque más débil.'], ['Un imán y un trozo de metal común', 'Las dos mitades siguen magnetizadas.']],
      'Los polos no se pueden separar.'),
    C('po-aluminio', 'polos', 2, '¿Cuál de estos materiales es atraído por un imán de refrigerador?', 'Un clavo de hierro',
      [['Una lata de aluminio', 'El aluminio no es ferromagnético.'], ['Una moneda de cobre', 'El cobre no es ferromagnético.'], ['Un trozo de vidrio', 'El vidrio no es atraído por un imán común.']],
      'Los imanes atraen hierro, níquel, cobalto y sus aleaciones.'),
    C('po-aguja', 'polos', 1, 'En una brújula, el extremo marcado N de la aguja es…', 'un polo norte del imán que es la aguja',
      [['un polo sur del imán que es la aguja', 'El extremo que busca el norte geográfico se llama polo norte.'], ['una carga eléctrica positiva', 'Los polos magnéticos no son cargas eléctricas.'], ['el extremo que apunta a los imanes cercanos', 'Apunta según el campo total; hacia un imán cercano apunta su extremo S, no el N.']],
      'La aguja es un imán pequeño; su extremo N es un polo norte.'),
    C('po-clip', 'polos', 2, 'Un imán atrae un clip de acero que no estaba magnetizado. ¿Por qué?', 'Porque el campo del imán magnetiza el clip y le crea polos',
      [['Porque el clip tiene carga eléctrica', 'El clip es neutro; la atracción es magnética, no eléctrica.'], ['Porque el clip ya era un imán', 'Un clip sin magnetizar también es atraído.'], ['Porque el aire empuja al clip contra el imán', 'El aire no interviene; es el campo magnético.']],
      'El campo induce polos en el clip: se atrae su extremo más cercano.'),
    C('po-clip-polo', 'polos', 3, 'Acercas el polo N de un imán a un clip de acero. El extremo del clip más cercano al imán se vuelve…', 'un polo S inducido',
      [['un polo N inducido', 'Un polo N se repelería y el clip no sería atraído.'], ['una carga positiva', 'No es carga eléctrica sino un polo magnético inducido.'], ['neutro: no se magnetiza', 'Sí se magnetiza: por eso es atraído.']],
      'El extremo cercano queda con polo opuesto al del imán, y por eso hay atracción.'),
    C('po-giro', 'polos', 2, 'Dos imanes de barra se repelen por sus extremos enfrentados. Giras uno de ellos 180° y los vuelves a acercar. ¿Qué ocurre?', 'Se atraen',
      [['Se siguen repeliendo', 'Al girarlo, enfrentas polos distintos.'], ['No hay fuerza entre ellos', 'La fuerza siempre existe cuando se acercan lo suficiente.'], ['Se atraen solo si los tocas', 'La fuerza actúa a distancia.']],
      'Girar 180° cambia el polo que se enfrenta: de iguales a distintos.'),
    C('po-monopolo', 'polos', 2, 'Hasta hoy, ¿qué se ha observado sobre los polos magnéticos aislados (monopolos)?', 'Nunca se ha observado un polo N o S solo',
      [['Se obtienen partiendo un imán muy pequeño', 'Cada trozo, por pequeño que sea, conserva sus dos polos.'], ['Se ven en todos los imanes de neodimio', 'Ningún imán, de ningún material, ha mostrado un polo solo.'], ['Solo existen polos N sueltos', 'No se ha observado ni N suelto ni S suelto.']],
      'Los polos siempre vienen en pares.'),
    C('po-nombre', 'polos', 2, '¿Por qué el extremo de un imán que apunta al norte geográfico se llama “polo norte”?', 'Por el extremo que “busca el norte”; es solo un nombre histórico',
      [['Porque está cargado positivamente', 'El magnetismo no es carga eléctrica.'], ['Porque siempre es más fuerte que el polo sur', 'Los dos polos de un imán de barra son igual de fuertes.'], ['Porque contiene el norte de la Tierra', 'El nombre viene de la dirección que señala, no de su contenido.']],
      'Es un nombre histórico: “norte-buscador”.'),
    C('po-atraer-dos', 'polos', 2, 'Un imán A atrae a un imán B. B repele a un imán C. Con esa información, A y C…', 'no se puede saber sin más información',
      [['siempre se atraen', 'Depende de qué extremos se enfrenten.'], ['siempre se repelen', 'Depende de qué extremos se enfrenten.'], ['nunca interactúan', 'Dos imanes cualesquiera interactúan.']],
      'Depende de cómo estén orientados A y C.'),
    C('po-origen', 'polos', 3, '¿Cuál es el origen del magnetismo de un imán permanente?', 'El movimiento de los electrones de sus átomos (órbita y espín)',
      [['Pequeños polos N y S sueltos acumulados en los extremos', 'No existen polos sueltos.'], ['Carga eléctrica neta positiva en el polo N', 'Un imán es eléctricamente neutro.'], ['Un fluido magnético que se acumula en los extremos', 'No existe tal fluido; es un efecto de los electrones.']],
      'Cada átomo se comporta como un imán diminuto, y en un imán permanente están alineados.'),
    N('po-n-pedazos', 'polos', 1, { n: [2, 9, 1] },
      function (v) { return 'Partes un imán de barra en $' + v.n + '$ pedazos. ¿Cuántos imanes tienes?'; },
      function (v) { return v.n; }, 'Cada pedazo es un imán completo.', {},
      function (v, LM) { return v.n; }),
    N('po-n-polos', 'polos', 2, { m: [2, 8, 1] },
      function (v) { return 'Partes un imán de barra en $' + v.m + '$ pedazos. ¿Cuántos polos N hay en total?'; },
      function (v) { return v.m; }, 'Cada pedazo tiene un polo N y un polo S.', {},
      function (v, LM) { return v.m; }),
    N('po-n-cortes', 'polos', 2, { c: [1, 8, 1] },
      function (v) { return 'Haces $' + v.c + '$ cortes a un imán de barra, todos perpendiculares a su eje. ¿Cuántos polos (N y S juntos) hay en total?'; },
      function (v) { return 2 * (v.c + 1); }, 'Con $c$ cortes hay $c + 1$ pedazos, cada uno con 2 polos.', {},
      function (v, LM) { return 2 * (v.c + 1); }),
    C('po-limadura', 'polos', 2, 'Si riegas limadura de hierro sobre un papel colocado encima de un imán, la limadura…', 'se acomoda siguiendo la dirección del campo magnético',
      [['se queda quieta, porque el papel la aísla del imán', 'El papel no bloquea el campo magnético.'], ['se junta toda en el centro del imán', 'Se concentra cerca de los polos y se alinea con las líneas de campo.'], ['se carga con electricidad estática', 'El efecto es magnético, no electrostático.']],
      'Cada granito se magnetiza y se alinea con $\\vec B$.'),

    /* ======================= El campo B y la brújula ======================= */
    C('ca-def', 'campo', 1, '¿Qué es el campo magnético $\\vec B$?', 'Una cantidad vectorial que existe en cada punto del espacio cerca de un imán',
      [['Una cantidad escalar que solo existe dentro del imán', 'Es un vector y existe también fuera del imán.'], ['La carga eléctrica de los polos', 'Los polos no son cargas eléctricas.'], ['El material de que está hecho el imán', 'Es el campo que produce el imán en su entorno, no el imán.']],
      '$\\vec B$ es un campo vectorial.'),
    C('ca-unidad', 'campo', 1, '¿Cuál es la unidad del campo magnético en el SI?', 'El tesla (T)',
      [['El coulomb (C)', 'El coulomb es la unidad de carga eléctrica.'], ['El newton (N)', 'El newton es la unidad de fuerza.'], ['El volt (V)', 'El volt es la unidad de potencial eléctrico.']],
      'La unidad de B es el tesla.'),
    C('ca-dir', 'campo', 1, '¿Cómo se determina la dirección de $\\vec B$ en un punto con una brújula?', 'Es la dirección que señala el extremo N de la aguja',
      [['Es la dirección que señala el extremo S de la aguja', 'El extremo S señala al revés: contra $\\vec B$.'], ['Es perpendicular a la aguja', 'La aguja se alinea con $\\vec B$, no perpendicular.'], ['No se puede medir con una brújula', 'La brújula es el detector clásico de la dirección de $\\vec B$.']],
      'La aguja se alinea con $\\vec B$.'),
    C('ca-vector', 'campo', 1, 'Si en un punto hay dos imanes, el campo magnético total es…', 'la suma vectorial de los campos de cada imán',
      [['la suma de las magnitudes, sin importar la dirección', 'Los campos son vectores: se suman con su dirección.'], ['el campo del imán más cercano, ignorando al otro', 'Los dos imanes contribuyen.'], ['el promedio de los dos campos', 'Se suman, no se promedian.']],
      'Principio de superposición: $\\vec B = \\vec B_1 + \\vec B_2$.'),
    C('ca-aguja-S', 'campo', 2, 'Una brújula está sobre el eje de un imán de barra, justo frente al polo S del imán. El extremo N de la aguja apunta…', 'hacia el imán',
      [['alejándose del imán', 'Las líneas entran por el polo S: ahí $\\vec B$ apunta hacia el imán.'], ['perpendicular al eje del imán', 'Sobre el eje, $\\vec B$ es paralelo al eje.'], ['en una dirección al azar', 'Tiene una dirección bien definida.']],
      'Las líneas entran por el polo S, así que $\\vec B$ apunta hacia el imán.'),
    C('ca-aguja-N', 'campo', 2, 'Una brújula está sobre el eje de un imán de barra, justo frente al polo N del imán. El extremo N de la aguja apunta…', 'alejándose del imán',
      [['hacia el imán', 'Las líneas salen del polo N: ahí $\\vec B$ se aleja del imán.'], ['perpendicular al eje del imán', 'Sobre el eje, $\\vec B$ es paralelo al eje.'], ['hacia el norte geográfico sin importar el imán', 'Cerca de un imán, el campo del imán domina al de la Tierra.']],
      'Las líneas salen del polo N.'),
    C('ca-medio', 'campo', 3, 'Dos imanes iguales se enfrentan con sus polos N, separados una distancia fija, en un cuarto sin campo de la Tierra. En el punto medio sobre el eje, $\\vec B$ vale…', 'cero, porque los campos de los dos imanes son iguales y opuestos',
      [['el doble del campo de un imán', 'Los campos apuntan en sentidos contrarios: se cancelan.'], ['el campo de un solo imán', 'Los dos contribuyen, con igual magnitud y sentidos opuestos.'], ['no se puede decir nada del campo', 'Por simetría se cancelan.']],
      'Por simetría, los campos son iguales y de sentido contrario en el punto medio.'),
    C('ca-bisect', 'campo', 2, 'Una brújula está en la mediatriz de un imán de barra (equidistante de sus dos polos), en un cuarto sin la Tierra. El campo $\\vec B$ en ese punto es…', 'paralelo al eje del imán y de sentido de N a S (opuesto al sentido interno)',
      [['perpendicular al eje del imán', 'Las componentes perpendiculares al eje se cancelan.'], ['cero', 'Las componentes paralelas al eje se suman.'], ['paralelo al eje y de sentido de S a N', 'Afuera del imán, B va de N a S; el sentido de S a N es el de adentro.']],
      'Las componentes perpendiculares al eje se cancelan; las paralelas se suman y apuntan de N a S.'),
    C('ca-escalar', 'campo', 2, 'Ana dice que el campo magnético en un punto se describe con un solo número. ¿Es correcto?', 'No: además de la magnitud necesita una dirección',
      [['Sí: solo importa cuán fuerte es', 'Es un vector: tiene magnitud y dirección.'], ['Sí: la dirección siempre es la del norte', 'La dirección cambia de punto a punto.'], ['No: necesita dos números, uno por cada polo', 'No se describe por polos; se describe por vectores.']],
      '$\\vec B$ es un vector.'),
    N('ca-pit', 'campo', 1, { a: [3, 12, 1], b: [4, 16, 1] },
      function (v) { return 'En un punto, dos fuentes dan campos perpendiculares de $' + v.a + '\\ \\text{mT}$ y $' + v.b + '\\ \\text{mT}$. ¿Cuánto vale el campo total, en mT?'; },
      function (v) { return Math.hypot(v.a, v.b); }, 'Perpendiculares: $|\\vec B| = \\sqrt{B_1^2 + B_2^2}$.',
      { unit: 'mT', mistakes: { sum: function (v) { return v.a + v.b; } }, feedback: [{ when: 'sum', say: 'Sumaste magnitudes. Como son perpendiculares, usa Pitágoras.' }] },
      function (v, LM) { return perp(LM, v.a, v.b).mag; }),
    N('ca-comp-E', 'campo', 2, { B: [2, 9, 1], th: [10, 80, 10] },
      function (v) { return 'Un campo de $' + v.B + '\\ \\text{mT}$ apunta a $' + v.th + '^\\circ$ del norte hacia el este. ¿Cuánto vale su componente hacia el <strong>este</strong>, en mT?'; },
      function (v) { return v.B * Math.sin(v.th / DEG); }, 'Desde el norte, la componente este es $B\\sin\\theta$.',
      { unit: 'mT', mistakes: { cos: function (v) { return v.B * Math.cos(v.th / DEG); } }, feedback: [{ when: 'cos', say: 'Esa es la componente hacia el norte. Desde el norte, la del este lleva el seno.' }]},
      function (v, LM) { return MG(LM).combine([{ mag: v.B, bearing: v.th }]).east; }),
    N('ca-comp-N', 'campo', 2, { Bn: [2, 9, 1], tn: [10, 80, 10] },
      function (v) { return 'Un campo de $' + v.Bn + '\\ \\text{mT}$ apunta a $' + v.tn + '^\\circ$ del norte hacia el este. ¿Cuánto vale su componente hacia el <strong>norte</strong>, en mT?'; },
      function (v) { return v.Bn * Math.cos(v.tn / DEG); }, 'Desde el norte, la componente norte es $B\\cos\\theta$.',
      { unit: 'mT', mistakes: { sin: function (v) { return v.Bn * Math.sin(v.tn / DEG); } }, feedback: [{ when: 'sin', say: 'Esa es la componente hacia el este. Desde el norte, la del norte lleva el coseno.' }] },
      function (v, LM) { return MG(LM).combine([{ mag: v.Bn, bearing: v.tn }]).north; }),
    N('ca-rumbo', 'campo', 2, { cn: [20, 80, 10], ce: [10, 70, 10] },
      function (v) { return 'En una brújula el campo total tiene $' + v.cn + '\\ \\mu\\text{T}$ hacia el norte y $' + v.ce + '\\ \\mu\\text{T}$ hacia el este. ¿A cuántos grados del norte hacia el este apunta la aguja?'; },
      function (v) { return Math.atan(v.ce / v.cn) * DEG; }, '$\\tan\\theta = B_E/B_N$.',
      { unit: '°', mistakes: { inverse: function (v) { return Math.atan(v.cn / v.ce) * DEG; } }, feedback: [{ when: 'inverse', say: 'Ese ángulo se mide desde el este. Desde el norte, $\\tan\\theta = B_E/B_N$.' }] },
      function (v, LM) { return perp(LM, v.ce, v.cn).bearing; }),
    N('ca-cuadrante', 'campo', 3, { w: [10, 60, 10], s: [10, 60, 10] },
      function (v) { return 'En una brújula el campo total tiene $' + v.w + '\\ \\mu\\text{T}$ hacia el <strong>oeste</strong> y $' + v.s + '\\ \\mu\\text{T}$ hacia el <strong>sur</strong>. ¿Qué rumbo señala la aguja, medido desde el norte hacia el este (de 0° a 360°)?'; },
      function (v) { return 180 + Math.atan(v.w / v.s) * DEG; }, 'Está en el cuadrante suroeste: $180^\\circ + \\tan^{-1}(B_O/B_S)$.',
      { unit: '°', mistakes: { s1: function (v) { return Math.atan(v.w / v.s) * DEG; }, s2: function (v) { return 180 - Math.atan(v.w / v.s) * DEG; } }, feedback: [{ when: 's1', say: 'Ese ángulo es del cuadrante noreste. Con oeste y sur la aguja apunta al suroeste: suma 180°.' }, { when: 's2', say: 'Ese ángulo es del cuadrante sureste. Revisa que el campo apunta al oeste, no al este.' }] },
      function (v, LM) { return MG(LM).combine([{ mag: v.w, bearing: 270 }, { mag: v.s, bearing: 180 }]).bearing; }),

    /* ======================= Líneas de campo ======================= */
    C('li-salen', 'lineas', 1, 'Fuera de un imán de barra, las líneas de campo…', 'salen del polo N y entran por el polo S',
      [['salen del polo S y entran por el polo N', 'Es al revés: salen del N.'], ['salen de los dos polos', 'No hay polos que “emitan”: salen de N y entran por S.'], ['son rectas paralelas al imán', 'Son curvas que unen un polo con otro.']],
      'Convención: afuera, de N a S.'),
    C('li-tangente', 'lineas', 1, 'En un punto de una línea de campo, el vector $\\vec B$ es…', 'tangente a la línea',
      [['perpendicular a la línea', 'La línea sigue la dirección de $\\vec B$, no es perpendicular a ella.'], ['paralelo al imán', 'Depende del punto: sigue la tangente.'], ['siempre cero', '$\\vec B$ no es cero en una línea de campo.']],
      'La línea es tangente a $\\vec B$ en cada punto.'),
    C('li-cruce', 'lineas', 1, '¿Pueden cruzarse dos líneas de campo magnético?', 'No: en cada punto $\\vec B$ tiene una sola dirección',
      [['Sí, cuando hay dos imanes', 'Aun con dos imanes, el campo total tiene una dirección en cada punto.'], ['Sí, cerca de los polos', 'Cerca de los polos las líneas se juntan pero no se cruzan.'], ['Sí, siempre se cruzan en el centro del imán', 'Nunca se cruzan.']],
      'Si se cruzaran, habría dos direcciones de $\\vec B$ en un punto.'),
    C('li-densidad', 'lineas', 1, 'Si en un dibujo las líneas de campo están más juntas en una región, ahí el campo es…', 'más intenso',
      [['más débil', 'Más juntas significa más intenso.'], ['igual de intenso', 'La densidad de líneas indica la intensidad.'], ['cero', 'Las líneas no existen donde $B = 0$.']],
      'La densidad de líneas indica la intensidad del campo.'),
    C('li-flecha', 'lineas', 1, 'La flecha dibujada sobre una línea de campo indica…', 'el sentido de $\\vec B$ en esa línea',
      [['el sentido en que viaja una partícula', 'No es la trayectoria de una partícula.'], ['dónde está el polo sur', 'Indica el sentido del campo, no el de los polos.'], ['la dirección de la fuerza sobre el imán', 'Indica el sentido de $\\vec B$.']],
      'La flecha muestra el sentido de $\\vec B$.'),
    C('li-cerradas', 'lineas', 2, 'Las líneas de campo magnético de un imán de barra, ¿empiezan o terminan en algún punto?', 'No: son lazos cerrados; adentro del imán van de S a N',
      [['Sí: empiezan en el polo N y terminan en el polo S', 'Siguen dentro del imán, de S a N, y cierran el lazo.'], ['Sí: empiezan en el centro del imán', 'No hay un punto de inicio.'], ['Sí: terminan donde se acaba el campo', 'Las líneas no “terminan” donde el campo es débil; solo se separan.']],
      'Las líneas de $\\vec B$ forman lazos cerrados.'),
    C('li-dentro', 'lineas', 2, 'Dentro de un imán de barra, las líneas de campo van…', 'del polo S al polo N',
      [['del polo N al polo S', 'Eso es lo que hacen afuera.'], ['no hay líneas adentro', 'Sí hay: cierran los lazos.'], ['de un lado a otro en zigzag', 'Son paralelas al eje del imán.']],
      'Afuera de N a S; adentro de S a N.'),
    C('li-diagrama', 'lineas', 3, 'Un estudiante dibuja las líneas de un imán que empiezan en el polo N y terminan en el polo S, y las deja ahí. ¿Qué le falta al dibujo?', 'Continuarlas por dentro del imán, de S a N, para cerrar cada lazo',
      [['Nada: así es el campo magnético', 'Falta la parte de adentro.'], ['Agregar cargas positivas en N y negativas en S', 'Los polos no son cargas.'], ['Hacer que las líneas se crucen en el centro', 'Nunca se cruzan.']],
      'El campo magnético no tiene fuentes puntuales: las líneas se cierran.'),
    C('li-atraen', 'lineas', 2, 'Con dos imanes enfrentados por polos N y S, las líneas de campo…', 'pasan de un imán al otro, como si los unieran',
      [['se apartan una de la otra', 'Eso ocurre con polos iguales.'], ['desaparecen entre los imanes', 'Entre polos distintos el campo es intenso.'], ['se cruzan entre los imanes', 'Las líneas no se cruzan.']],
      'Salen del N de uno y entran por el S del otro.'),
    C('li-repelen', 'lineas', 2, 'Con dos imanes enfrentados por polos iguales (N con N), las líneas de campo…', 'se empujan una a otra y se curvan en lugar de pasar de uno a otro',
      [['pasan directo de un imán al otro', 'Eso ocurre con polos distintos.'], ['se vuelven rectas y paralelas al eje', 'Se curvan alejándose del punto medio.'], ['se cruzan en el punto medio', 'Nunca se cruzan.']],
      'Entre polos iguales no hay líneas que pasen de un imán al otro.'),
    C('li-particula', 'lineas', 2, 'Una partícula cargada, ¿sigue una línea de campo magnético?', 'No: una línea solo da la dirección de $\\vec B$ en cada punto',
      [['Sí: siempre se mueve a lo largo de la línea', 'Eso valdría para la fuerza eléctrica sobre una carga en reposo, no para la magnética.'], ['Sí, si es negativa', 'La carga no cambia eso.'], ['Solo si su rapidez es muy grande', 'La rapidez no cambia la naturaleza de una línea de campo.']],
      'Las líneas son un dibujo del campo, no trayectorias.'),
    C('li-EB', 'lineas', 2, 'Una diferencia entre las líneas de $\\vec E$ de un dipolo eléctrico y las de $\\vec B$ de un imán es que las de $\\vec E$…', 'empiezan en la carga positiva y terminan en la negativa, y las de $\\vec B$ se cierran',
      [['se cruzan y las de $\\vec B$ no', 'Ninguna se cruza.'], ['son lazos cerrados y las de $\\vec B$ no', 'Es al revés.'], ['no tienen sentido y las de $\\vec B$ sí', 'Las dos tienen sentido.']],
      'Las líneas de $\\vec E$ tienen fuentes (cargas); las de $\\vec B$ forman lazos.'),
    C('li-cero', 'lineas', 3, 'En el punto medio entre dos imanes iguales que se repelen (N con N), $\\vec B = 0$. En un dibujo, esto se ve como…', 'un punto donde no pasa ninguna línea de campo',
      [['un punto donde se cruzan muchas líneas', 'Las líneas no se cruzan; ahí no hay líneas.'], ['un punto con las líneas más juntas', 'Donde $B = 0$ no hay líneas.'], ['un punto donde las líneas son paralelas', 'En $B = 0$ no hay dirección definida.']],
      'En un punto neutro $\\vec B = 0$ y no hay línea que pase.'),
    C('li-polos-fuerte', 'lineas', 2, 'Para un imán de barra, ¿dónde están más juntas las líneas de campo en un dibujo?', 'Junto a los polos',
      [['En el centro, afuera del imán', 'Afuera, en el centro, el campo es más débil.'], ['Lejos del imán', 'Lejos se separan.'], ['En cualquier parte, por igual', 'La densidad cambia.']],
      'Cerca de los polos el campo es más intenso.'),
    N('li-n-entran', 'lineas', 1, { n: [4, 20, 2] },
      function (v) { return 'En un dibujo de un imán de barra solo, salen $' + v.n + '$ líneas de campo del polo N. ¿Cuántas entran por el polo S?'; },
      function (v) { return v.n; }, 'Las líneas se cierran: no se crean ni se pierden.', {},
      function (v, LM) { return v.n; }),
    N('li-n-dentro', 'lineas', 2, { m: [3, 15, 1] },
      function (v) { return 'Un dibujo muestra $' + v.m + '$ líneas saliendo del polo N de un imán de barra y entrando por el S. ¿Cuántas líneas atraviesan una sección transversal en el centro del imán, <em>por dentro</em>?'; },
      function (v) { return v.m; }, 'Todas las líneas se cierran por dentro.', {},
      function (v, LM) { return v.m; }),

    /* ======================= El campo de la Tierra ======================= */
    C('ti-polo', 'tierra', 2, 'El polo magnético de la Tierra que está cerca del polo norte geográfico es, físicamente, un polo…', 'S (sur) del imán terrestre',
      [['N (norte) del imán terrestre', 'El N de una brújula es atraído a ese polo, y polos iguales se repelen.'], ['neutro, ni N ni S', 'Tiene signo magnético.'], ['que cambia de signo cada día', 'No cambia día con día.']],
      'El extremo N de la aguja es atraído por un polo S.'),
    C('ti-brujula', 'tierra', 1, 'Lejos de cualquier imán o pieza de hierro, el extremo N de una brújula apunta aproximadamente hacia…', 'el norte geográfico',
      [['el sur geográfico', 'Apunta hacia el norte.'], ['arriba, hacia el cielo', 'La aguja gira en un plano horizontal, por lo que apunta aproximadamente al norte.'], ['el este', 'Apunta hacia el norte, no hacia el este.']],
      'La brújula se alinea con el campo de la Tierra.'),
    C('ti-valor', 'tierra', 1, 'El campo magnético de la Tierra en la superficie es del orden de…', '$50\\ \\mu\\text{T}$',
      [['$50\\ \\text{T}$', 'Eso es mil millones de veces más que el de la Tierra.'], ['$50\\ \\text{mT}$', 'Eso es mil veces mayor que el campo terrestre.'], ['$50\\ \\text{nT}$', 'Es demasiado pequeño: el campo terrestre es de unas decenas de microteslas.']],
      'Unas decenas de microteslas, $\\approx 0.5\\ \\text{G}$.'),
    C('ti-lejos', 'tierra', 2, 'Una brújula está muy lejos de un imán pequeño. ¿Hacia dónde apunta?', 'Hacia el norte, porque el campo de la Tierra domina',
      [['Hacia el imán, sin importar la distancia', 'Lejos, el campo del imán es mucho menor que el de la Tierra.'], ['Hacia el sur', 'Apunta al norte.'], ['No apunta a ninguna parte', 'Siempre hay un campo total que define la dirección.']],
      'El campo de un imán disminuye rápido con la distancia; el de la Tierra es casi uniforme.'),
    C('ti-hierro', 'tierra', 2, 'Una brújula cerca de un cuchillo de acero se desvía del norte. ¿Por qué?', 'El acero se magnetiza y su campo se suma al de la Tierra',
      [['Porque el cuchillo tiene carga eléctrica', 'Un cuchillo común es neutro.'], ['Porque el acero bloquea el campo de la Tierra', 'El acero no bloquea el campo de la Tierra; añade el suyo.'], ['Porque la brújula pesa más cerca del cuchillo', 'El peso no afecta la dirección de la aguja.']],
      'El campo total es la suma del de la Tierra y el del acero magnetizado.'),
    C('ti-dec', 'tierra', 2, 'La declinación magnética en un lugar es…', 'el ángulo entre el norte magnético (lo que señala la brújula) y el norte geográfico',
      [['la fuerza del campo terrestre en ese lugar', 'La fuerza es la magnitud de $B$; la declinación es un ángulo.'], ['el ángulo entre el campo y la vertical', 'Eso se parece a la inclinación del campo, no a la declinación.'], ['la distancia al polo norte', 'Es un ángulo, no una distancia.']],
      'Una brújula no apunta exactamente al norte geográfico.'),
    C('ti-origen', 'tierra', 3, 'Se cree que el campo de la Tierra viene de…', 'corrientes eléctricas de metal líquido en el núcleo externo',
      [['un gran imán permanente de hierro en el centro', 'El núcleo está por encima de la temperatura a la que el hierro pierde el magnetismo permanente.'], ['cargas eléctricas atrapadas en la corteza', 'Las cargas estáticas no producen este campo.'], ['la radiación del Sol que se acumula', 'El campo existe aunque el Sol se apague; viene del interior.']],
      'El núcleo externo es líquido y se mueve; esas corrientes generan el campo.'),
    C('ti-lejos-fuerte', 'tierra', 3, 'Para que una brújula cerca de un imán se desvíe 45° del norte, el campo del imán en la brújula (perpendicular al de la Tierra) debe ser…', 'igual al campo de la Tierra',
      [['el doble del campo de la Tierra', 'Con el doble, la desviación sería mayor que 45° (unos 63°).'], ['la mitad del campo de la Tierra', 'Con la mitad, la desviación sería menor que 45° (unos 27°).'], ['cero', 'Con cero, no habría desviación.']],
      '$\\tan 45^\\circ = 1$, así que $B_{\\text{imán}} = B_{\\text{Tierra}}$.'),
    N('ti-G-uT', 'tierra', 1, { g: [0.25, 0.65, 0.05] },
      function (v) { return 'En un lugar el campo de la Tierra mide $' + fx(v.g, 2) + '\\ \\text{G}$. ¿Cuánto es en $\\mu\\text{T}$?'; },
      function (v) { return v.g * 100; }, '$1\\ \\text{G} = 100\\ \\mu\\text{T}$.',
      { unit: 'µT', mistakes: { mT: function (v) { return v.g * 0.1; } }, feedback: [{ when: 'mT', say: 'Ese valor está en militeslas. $1\\ \\text{G} = 100\\ \\mu\\text{T}$.' }] },
      function (v, LM) { return MG(LM).convert(v.g, 'G', 'uT'); }),
    N('ti-uT-G', 'tierra', 1, { u: [25, 65, 5] },
      function (v) { return 'El campo de la Tierra en una ciudad mide $' + v.u + '\\ \\mu\\text{T}$. ¿Cuánto es en gauss?'; },
      function (v) { return v.u / 100; }, '$1\\ \\text{G} = 100\\ \\mu\\text{T}$.',
      { unit: 'G', mistakes: { times: function (v) { return v.u * 100; } }, feedback: [{ when: 'times', say: 'Multiplicaste en lugar de dividir: $1\\ \\mu\\text{T} = 0.01\\ \\text{G}$.' }] },
      function (v, LM) { return MG(LM).convert(v.u, 'uT', 'G'); }),
    N('ti-veces', 'tierra', 2, { im: [1, 9, 1], tu: [25, 65, 5] },
      function (v) { return 'Un imán da $' + v.im + '\\ \\text{mT}$ junto a su polo y la Tierra $' + v.tu + '\\ \\mu\\text{T}$. ¿Cuántas veces mayor es el campo del imán?'; },
      function (v) { return v.im * 1000 / v.tu; }, 'Pasa los dos a $\\mu\\text{T}$ y divide.',
      { mistakes: { noConv: function (v) { return v.im / v.tu; } }, feedback: [{ when: 'noConv', say: 'Mezclaste mT con µT. $1\\ \\text{mT} = 10^{3}\\ \\mu\\text{T}$.' }] },
      function (v, LM) { return MG(LM).ratio(v.im, 'mT', v.tu, 'uT').ratio; }),
    N('ti-desv', 'tierra', 2, { k: [1, 4, 1] },
      function (v) { return 'Un imán produce en una brújula un campo hacia el este que es $' + v.k + '$ veces el de la Tierra (que apunta al norte). ¿Cuántos grados se desvía la aguja del norte hacia el este?'; },
      function (v) { return Math.atan(v.k) * DEG; }, '$\\tan\\theta = B_{\\text{imán}}/B_{\\text{Tierra}} = k$.',
      { unit: '°', mistakes: { inv: function (v) { return Math.atan(1 / v.k) * DEG; } }, feedback: [{ when: 'inv', say: 'Ese es el ángulo desde el este. Desde el norte, $\\tan\\theta = B_{\\text{imán}}/B_{\\text{Tierra}}$.' }], where: function (v) { return v.k !== 1; } },
      function (v, LM) { return perp(LM, v.k, 1).bearing; }),
    N('ti-fracc', 'tierra', 2, { fm: [1, 9, 1] },
      function (v) { return 'La Tierra aporta $50\\ \\mu\\text{T}$ y un imán de refrigerador $' + v.fm + '\\ \\text{mT}$. ¿Qué porcentaje del campo del imán es el de la Tierra?'; },
      function (v) { return 50 / (v.fm * 1000) * 100; }, 'Cociente en las mismas unidades, por 100.',
      { unit: '%', mistakes: { noConv: function (v) { return 0.05 / v.fm; } , x: function (v) { return 50 / v.fm; } }, feedback: [{ when: 'x', say: 'Mezclaste µT con mT. $1\\ \\text{mT} = 10^{3}\\ \\mu\\text{T}$.' }] },
      function (v, LM) { return 100 / MG(LM).ratio(v.fm, 'mT', 50, 'uT').ratio; }),
    N('ti-oeste', 'tierra', 3, { Bo: [20, 100, 10] },
      function (v) { return 'Un imán produce $' + v.Bo + '\\ \\mu\\text{T}$ hacia el <strong>oeste</strong> en una brújula y la Tierra $50\\ \\mu\\text{T}$ hacia el norte. ¿Qué rumbo señala la aguja, medido desde el norte hacia el este (de 0° a 360°)?'; },
      function (v) { return 360 - Math.atan(v.Bo / 50) * DEG; }, 'Está al noroeste: $360^\\circ - \\tan^{-1}(B_O/B_N)$.',
      { unit: '°', mistakes: { ne: function (v) { return Math.atan(v.Bo / 50) * DEG; } }, feedback: [{ when: 'ne', say: 'Ese rumbo es al noreste. El imán empuja la aguja hacia el oeste: el rumbo es 360° menos ese ángulo.' }], where: function (v) { return v.Bo !== 50; } },
      function (v, LM) { return MG(LM).combine([{ mag: v.Bo, bearing: 270 }, { mag: 50, bearing: 0 }]).bearing; }),
    N('ti-cuanto', 'tierra', 3, { th: [10, 70, 10] },
      function (v) { return 'Un imán desvía la aguja de una brújula $' + v.th + '^\\circ$ del norte hacia el este. Su campo en la brújula es perpendicular al de la Tierra ($50\\ \\mu\\text{T}$). ¿Cuánto vale el campo del imán, en $\\mu\\text{T}$?'; },
      function (v) { return 50 * Math.tan(v.th / DEG); }, '$B_{\\text{imán}} = B_{\\text{Tierra}}\\tan\\theta$.',
      { unit: 'µT', mistakes: { sin: function (v) { return 50 * Math.sin(v.th / DEG); }, cos: function (v) { return 50 / Math.cos(v.th / DEG); } }, feedback: [{ when: 'sin', say: 'Usaste el seno. Como el campo de la Tierra es la componente adyacente, la tangente relaciona los dos campos.' }] },
      function (v, LM) { var t = Math.tan(v.th / DEG); return perp(LM, 50 * t, 50).mag * Math.sin(v.th / DEG); }),

    /* ======================= Unidades y órdenes de magnitud ======================= */
    N('un-mT-G', 'unidades', 1, { B: [0.5, 9.5, 0.5] },
      function (v) { return 'Un campo mide $' + fx(v.B, 1) + '\\ \\text{mT}$. ¿Cuánto es en gauss?'; },
      function (v) { return v.B * 10; }, '$1\\ \\text{mT} = 10\\ \\text{G}$.',
      { unit: 'G', mistakes: { same: function (v) { return v.B; }, micro: function (v) { return v.B * 1000; } }, feedback: [{ when: 'same', say: 'Pasa de mT a G: $1\\ \\text{mT} = 10\\ \\text{G}$.' }, { when: 'micro', say: 'Ese valor está en µT. $1\\ \\text{mT} = 10\\ \\text{G}$.' }] },
      function (v, LM) { return MG(LM).convert(v.B, 'mT', 'G'); }),
    N('un-G-uT', 'unidades', 1, { G: [1, 9, 1] },
      function (v) { return 'Un campo mide $' + v.G + '\\ \\text{G}$. ¿Cuánto es en $\\mu\\text{T}$?'; },
      function (v) { return v.G * 100; }, '$1\\ \\text{G} = 100\\ \\mu\\text{T}$.',
      { unit: 'µT', mistakes: { thousand: function (v) { return v.G * 1000; } }, feedback: [{ when: 'thousand', say: '$1\\ \\text{G} = 100\\ \\mu\\text{T}$, no 1000.' }] },
      function (v, LM) { return MG(LM).convert(v.G, 'G', 'uT'); }),
    N('un-T-G', 'unidades', 1, { T: [0.5, 3, 0.5] },
      function (v) { return 'Un equipo de resonancia genera $' + fx(v.T, 1) + '\\ \\text{T}$. ¿Cuánto es en gauss?'; },
      function (v) { return v.T * 1e4; }, '$1\\ \\text{T} = 10^{4}\\ \\text{G}$.',
      { unit: 'G', mistakes: { thousand: function (v) { return v.T * 1000; } }, feedback: [{ when: 'thousand', say: '$1\\ \\text{T} = 10^{4}\\ \\text{G}$ (diez mil), no mil.' }] },
      function (v, LM) { return MG(LM).convert(v.T, 'T', 'G'); }),
    N('un-T-mT', 'unidades', 1, { T: [0.1, 0.9, 0.1] },
      function (v) { return 'Un imán de neodimio mide $' + fx(v.T, 1) + '\\ \\text{T}$ junto a su polo. ¿Cuánto es en militesla?'; },
      function (v) { return v.T * 1000; }, '$1\\ \\text{T} = 10^{3}\\ \\text{mT}$.',
      { unit: 'mT', mistakes: { hundred: function (v) { return v.T * 100; } }, feedback: [{ when: 'hundred', say: '$1\\ \\text{T} = 1000\\ \\text{mT}$.' }] },
      function (v, LM) { return MG(LM).convert(v.T, 'T', 'mT'); }),
    N('un-uT-mT', 'unidades', 1, { u: [10, 90, 10] },
      function (v) { return 'Un campo mide $' + v.u + '\\ \\mu\\text{T}$. ¿Cuánto es en mT?'; },
      function (v) { return v.u / 1000; }, '$1\\ \\mu\\text{T} = 10^{-3}\\ \\text{mT}$.',
      { unit: 'mT', mistakes: { times: function (v) { return v.u * 1000; } }, feedback: [{ when: 'times', say: 'Multiplicaste en lugar de dividir: un microtesla es una milésima de militesla.' }] },
      function (v, LM) { return MG(LM).convert(v.u, 'uT', 'mT'); }),
    N('un-uT-T', 'unidades', 2, { u: [20, 90, 10] },
      function (v) { return 'El campo de la Tierra en un lugar mide $' + v.u + '\\ \\mu\\text{T}$. ¿Cuánto es en teslas?' + SCI; },
      function (v) { return v.u * 1e-6; }, '$1\\ \\mu\\text{T} = 10^{-6}\\ \\text{T}$.',
      { unit: 'T', mistakes: { mili: function (v) { return v.u * 1e-3; } }, feedback: [{ when: 'mili', say: 'Usaste mili ($10^{-3}$); es micro ($10^{-6}$).' }] },
      function (v, LM) { return MG(LM).convert(v.u, 'uT', 'T'); }),
    N('un-mT-T', 'unidades', 2, { m: [1, 9, 1] },
      function (v) { return 'Un imán de refrigerador mide $' + v.m + '\\ \\text{mT}$. ¿Cuánto es en teslas?' + SCI; },
      function (v) { return v.m * 1e-3; }, '$1\\ \\text{mT} = 10^{-3}\\ \\text{T}$.',
      { unit: 'T', mistakes: { micro: function (v) { return v.m * 1e-6; } }, feedback: [{ when: 'micro', say: 'Usaste micro ($10^{-6}$); es mili ($10^{-3}$).' }] },
      function (v, LM) { return MG(LM).convert(v.m, 'mT', 'T'); }),
    N('un-G-T', 'unidades', 2, { g: [1, 9, 1] },
      function (v) { return 'Un campo mide $' + v.g + '\\ \\text{G}$. ¿Cuánto es en teslas?' + SCI; },
      function (v) { return v.g * 1e-4; }, '$1\\ \\text{G} = 10^{-4}\\ \\text{T}$.',
      { unit: 'T', mistakes: { thousandth: function (v) { return v.g * 1e-3; } }, feedback: [{ when: 'thousandth', say: '$1\\ \\text{G} = 10^{-4}\\ \\text{T}$, no $10^{-3}$.' }] },
      function (v, LM) { return MG(LM).convert(v.g, 'G', 'T'); }),
    N('un-mri', 'unidades', 2, { t: [1.5, 3, 0.5] },
      function (v) { return 'Un equipo de resonancia genera $' + fx(v.t, 1) + '\\ \\text{T}$. ¿Cuántas veces mayor es que el campo de la Tierra ($50\\ \\mu\\text{T}$)?'; },
      function (v) { return v.t * 1e6 / 50; }, 'Pasa a $\\mu\\text{T}$ ($1\\ \\text{T} = 10^{6}\\ \\mu\\text{T}$) y divide.',
      { mistakes: { noConv: function (v) { return v.t / 50; } }, feedback: [{ when: 'noConv', say: 'Mezclaste T con µT. $1\\ \\text{T} = 10^{6}\\ \\mu\\text{T}$.' }] },
      function (v, LM) { return MG(LM).ratio(v.t, 'T', 50, 'uT').ratio; }),
    N('un-nd-refri', 'unidades', 2, { nd: [100, 500, 100], rf: [2, 8, 2] },
      function (v) { return 'Un imán de neodimio mide $' + v.nd + '\\ \\text{mT}$ y uno de refrigerador $' + v.rf + '\\ \\text{mT}$. ¿Cuántas veces mayor es el de neodimio?'; },
      function (v) { return v.nd / v.rf; }, 'Misma unidad: cociente.',
      { mistakes: { inverse: function (v) { return v.rf / v.nd; } }, feedback: [{ when: 'inverse', say: 'Invertiste el cociente.' }] },
      function (v, LM) { return MG(LM).ratio(v.nd, 'mT', v.rf, 'mT').ratio; }),
    N('un-suma', 'unidades', 3, { a: [1, 9, 1], b: [1, 9, 1] },
      function (v) { return 'Dos fuentes producen campos en la misma dirección y sentido: una de $' + v.a + '\\ \\text{mT}$ y otra de $' + v.b + '\\ \\text{G}$. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return v.a * 1000 + v.b * 100; }, 'Pasa los dos a $\\mu\\text{T}$ y suma: $1\\ \\text{mT} = 10^{3}\\ \\mu\\text{T}$, $1\\ \\text{G} = 100\\ \\mu\\text{T}$.',
      { unit: 'µT', mistakes: { raw: function (v) { return v.a + v.b; }, gaussWrong: function (v) { return v.a * 1000 + v.b * 1000; } }, feedback: [{ when: 'raw', say: 'Sumaste mT con G sin convertir.' }, { when: 'gaussWrong', say: '$1\\ \\text{G} = 100\\ \\mu\\text{T}$, no 1000.' }], where: function (v) { return v.a !== v.b; } },
      function (v, LM) { return MG(LM).convert(v.a, 'mT', 'uT') + MG(LM).convert(v.b, 'G', 'uT'); }),
    N('un-veces-G', 'unidades', 1, { x: [2, 20, 2] },
      function (v) { return 'Un campo mide $' + v.x + '\\ \\text{G}$. ¿Cuántas veces mayor es que el de la Tierra ($0.50\\ \\text{G}$)?'; },
      function (v) { return v.x / 0.5; }, 'Misma unidad: cociente.', {},
      function (v, LM) { return MG(LM).ratio(v.x, 'G', 0.5, 'G').ratio; }),
    C('un-mayor', 'unidades', 1, '¿Cuál de estos campos es el mayor?', '$1\\ \\text{T}$',
      [['$1\\ \\text{mT}$', 'Un militesla es mil veces menor que un tesla.'], ['$1\\ \\text{G}$', 'Un gauss es $10^{-4}\\ \\text{T}$.'], ['$1\\ \\mu\\text{T}$', 'Un microtesla es un millón de veces menor que un tesla.']],
      '$1\\ \\text{T} = 10^{4}\\ \\text{G} = 10^{3}\\ \\text{mT} = 10^{6}\\ \\mu\\text{T}$.'),
    C('un-prefijo', 'unidades', 2, '¿A cuántos microteslas equivale un militesla?', '$1000\\ \\mu\\text{T}$',
      [['$10\\ \\mu\\text{T}$', 'Eso es la equivalencia con gauss.'], ['$0.001\\ \\mu\\text{T}$', 'Es al revés: un militesla es mayor.'], ['$100\\ \\mu\\text{T}$', 'Eso sería un gauss.']],
      '$1\\ \\text{mT} = 10^{-3}\\ \\text{T} = 10^{3}\\ \\mu\\text{T}$.'),
    C('un-gauss', 'unidades', 2, 'El gauss (G) es una unidad de…', 'campo magnético, y $1\\ \\text{T} = 10^{4}\\ \\text{G}$',
      [['carga eléctrica, y $1\\ \\text{C} = 10^{4}\\ \\text{G}$', 'El gauss mide campo magnético.'], ['fuerza magnética, y $1\\ \\text{N} = 10^{4}\\ \\text{G}$', 'Mide campo, no fuerza.'], ['campo magnético, y $1\\ \\text{T} = 10^{-4}\\ \\text{G}$', 'Es al revés: un tesla son $10^{4}$ gauss.']],
      'El gauss es una unidad de campo magnético fuera del SI.'),
    C('un-orden', 'unidades', 2, 'Ordena de menor a mayor: campo de la Tierra, imán de refrigerador y equipo de resonancia magnética.', 'Tierra, imán de refrigerador, resonancia magnética',
      [['Imán de refrigerador, Tierra, resonancia magnética', 'La Tierra ($\\sim 50\\ \\mu\\text{T}$) es más débil que el imán de refrigerador ($\\sim 5\\ \\text{mT}$).'], ['Resonancia magnética, imán de refrigerador, Tierra', 'Ese orden es de mayor a menor.'], ['Tierra, resonancia magnética, imán de refrigerador', 'La resonancia ($\\sim 1.5\\ \\text{T}$) es la mayor de las tres.']],
      '$50\\ \\mu\\text{T} < 5\\ \\text{mT} < 1.5\\ \\text{T}$.'),
    C('un-tesla-G', 'unidades', 1, 'Para pasar un campo de teslas a gauss, debes…', 'multiplicar por $10^{4}$',
      [['dividir entre $10^{4}$', 'Al revés: un tesla son diez mil gauss.'], ['multiplicar por $10^{3}$', 'Eso es de teslas a militeslas.'], ['multiplicar por $10^{6}$', 'Eso es de teslas a microteslas.']],
      '$1\\ \\text{T} = 10^{4}\\ \\text{G}$.'),
    C('un-ejemplo', 'unidades', 2, '¿Cuál de estos valores es el más razonable para el campo de un imán de refrigerador junto a su superficie?', '$5\\ \\text{mT}$',
      [['$5\\ \\text{T}$', 'Esos campos son de equipos de resonancia, no de imanes de refrigerador.'], ['$5\\ \\text{nT}$', 'Es mucho menor que el campo de la Tierra.'], ['$5\\ \\mu\\text{T}$', 'Eso es menor que el campo de la Tierra; un imán de refrigerador es mucho más fuerte.']],
      'Del orden de unos militeslas.'),
    C('un-SI', 'unidades', 3, 'Una calculadora da el campo de un imán como $0.005$ en teslas. ¿Cuál es el mismo valor en la unidad más conveniente?', '$5\\ \\text{mT}$',
      [['$5\\ \\mu\\text{T}$', '$0.005\\ \\text{T} = 5\\times10^{-3}\\ \\text{T} = 5\\ \\text{mT}$, no $5\\ \\mu\\text{T}$.'], ['$50\\ \\text{mT}$', '$0.005\\ \\text{T} = 5\\ \\text{mT}$.'], ['$0.5\\ \\text{mT}$', '$0.005\\ \\text{T} = 5\\ \\text{mT}$.']],
      '$0.005\\ \\text{T} = 5\\times 10^{-3}\\ \\text{T} = 5\\ \\text{mT}$.'),

    /* ======================= Suma de campos ======================= */
    N('su-pit', 'suma', 1, { c: [30, 120, 10], d: [40, 150, 10] },
      function (v) { return 'Sobre una brújula, un imán da $' + v.c + '\\ \\mu\\text{T}$ hacia el este y otro da $' + v.d + '\\ \\mu\\text{T}$ hacia el norte. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return Math.hypot(v.c, v.d); }, 'Perpendiculares: Pitágoras.',
      { unit: 'µT', mistakes: { sum: function (v) { return v.c + v.d; } }, feedback: [{ when: 'sum', say: 'Sumaste magnitudes. Son perpendiculares: usa Pitágoras.' }], where: function (v) { return v.c !== v.d; } },
      function (v, LM) { return perp(LM, v.c, v.d).mag; }),
    N('su-345', 'suma', 1, { k: [1, 10, 1] },
      function (v) { return 'Dos campos perpendiculares miden $' + 3 * v.k + '\\ \\text{mT}$ y $' + 4 * v.k + '\\ \\text{mT}$. ¿Cuánto vale el campo total, en mT?'; },
      function (v) { return 5 * v.k; }, 'Terna pitagórica 3–4–5.',
      { unit: 'mT', mistakes: { sum: function (v) { return 7 * v.k; } }, feedback: [{ when: 'sum', say: 'Sumaste magnitudes; son perpendiculares.' }] },
      function (v, LM) { return perp(LM, 3 * v.k, 4 * v.k).mag; }),
    N('su-misma', 'suma', 1, { a: [10, 90, 10], b: [10, 90, 10] },
      function (v) { return 'Dos imanes producen en una brújula campos de $' + v.a + '\\ \\mu\\text{T}$ y $' + v.b + '\\ \\mu\\text{T}$, los dos hacia el este. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return v.a + v.b; }, 'Misma dirección y sentido: se suman.',
      { unit: 'µT', mistakes: { pit: function (v) { return Math.hypot(v.a, v.b); } }, feedback: [{ when: 'pit', say: 'Aplicaste Pitágoras, pero los campos tienen la misma dirección.' }] },
      function (v, LM) { return MG(LM).combine([{ mag: v.a, bearing: 90 }, { mag: v.b, bearing: 90 }]).mag; }),
    N('su-opuestos', 'suma', 1, { p: [60, 150, 10], q: [10, 50, 10] },
      function (v) { return 'Un imán da $' + v.p + '\\ \\mu\\text{T}$ hacia el este y otro $' + v.q + '\\ \\mu\\text{T}$ hacia el oeste. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return v.p - v.q; }, 'Sentidos opuestos: se restan.',
      { unit: 'µT', mistakes: { sum: function (v) { return v.p + v.q; } }, feedback: [{ when: 'sum', say: 'Sentidos opuestos se restan.' }] },
      function (v, LM) { return MG(LM).combine([{ mag: v.p, bearing: 90 }, { mag: v.q, bearing: 270 }]).mag; }),
    N('su-rumbo', 'suma', 2, { e: [20, 80, 10], n: [20, 80, 10] },
      function (v) { return 'Un imán da $' + v.e + '\\ \\mu\\text{T}$ hacia el este y otro $' + v.n + '\\ \\mu\\text{T}$ hacia el norte. ¿Qué rumbo señala la aguja, medido desde el norte hacia el este?'; },
      function (v) { return Math.atan(v.e / v.n) * DEG; }, '$\\tan\\theta = B_E/B_N$.',
      { unit: '°', mistakes: { inv: function (v) { return Math.atan(v.n / v.e) * DEG; } }, feedback: [{ when: 'inv', say: 'Ese ángulo se mide desde el este. Desde el norte: $\\tan\\theta = B_E/B_N$.' }], where: function (v) { return v.e !== v.n; } },
      function (v, LM) { return perp(LM, v.e, v.n).bearing; }),
    N('su-tres', 'suma', 2, { t: [40, 100, 10], a: [10, 60, 10], b: [10, 30, 10] },
      function (v) { return 'Sobre una brújula actúan: $' + v.t + '\\ \\mu\\text{T}$ al norte, $' + v.a + '\\ \\mu\\text{T}$ al este y $' + v.b + '\\ \\mu\\text{T}$ al sur. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return Math.hypot(v.a, v.t - v.b); }, 'Norte neto: $t - b$; este: $a$. Luego Pitágoras.',
      { unit: 'µT', mistakes: { nosur: function (v) { return Math.hypot(v.a, v.t); }, sumsur: function (v) { return Math.hypot(v.a, v.t + v.b); } }, feedback: [{ when: 'nosur', say: 'Olvidaste el campo hacia el sur: resta al del norte.' }, { when: 'sumsur', say: 'El campo hacia el sur resta al del norte, no suma.' }] },
      function (v, LM) { return MG(LM).combine([{ mag: v.t, bearing: 0 }, { mag: v.a, bearing: 90 }, { mag: v.b, bearing: 180 }]).mag; }),
    N('su-n-imanes', 'suma', 2, { n: [2, 9, 1], b: [10, 40, 10] },
      function (v) { return 'En una brújula, $' + v.n + '$ imanes idénticos dan cada uno $' + v.b + '\\ \\mu\\text{T}$, todos en la misma dirección y sentido. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return v.n * v.b; }, 'Misma dirección y sentido: se suman.', { unit: 'µT' },
      function (v, LM) { var l = []; for (var i = 0; i < v.n; i++) l.push({ mag: v.b, bearing: 45 }); return MG(LM).combine(l).mag; }),
    N('su-dos-ang', 'suma', 3, { a: [20, 80, 10], b: [20, 80, 10], r0: [10, 60, 10] },
      function (v) { return 'Un campo de $' + v.a + '\\ \\mu\\text{T}$ apunta a $' + v.r0 + '^\\circ$ del norte hacia el este, y otro de $' + v.b + '\\ \\mu\\text{T}$ apunta a $' + (v.r0 + 90) + '^\\circ$ (perpendicular al primero). ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return Math.hypot(v.a, v.b); }, 'Los dos campos son perpendiculares entre sí, aunque no estén sobre los ejes.',
      { unit: 'µT', mistakes: { sum: function (v) { return v.a + v.b; } }, feedback: [{ when: 'sum', say: 'Sumaste magnitudes. Los dos campos son perpendiculares entre sí: Pitágoras.' }], where: function (v) { return v.a !== v.b; } },
      function (v, LM) { return MG(LM).combine([{ mag: v.a, bearing: v.r0 }, { mag: v.b, bearing: v.r0 + 90 }]).mag; }),
    N('su-razon', 'suma', 3, { th: [20, 70, 10], bt: [30, 60, 10] },
      function (v) { return 'La Tierra aporta $' + v.bt + '\\ \\mu\\text{T}$ al norte. Un imán, perpendicular a ese campo, hace que la aguja se desvíe $' + v.th + '^\\circ$. ¿Cuánto vale el campo <em>total</em> en la brújula, en $\\mu\\text{T}$?'; },
      function (v) { return v.bt / Math.cos(v.th / DEG); }, '$B_{\\text{Tierra}} = B\\cos\\theta$, así que $B = B_{\\text{Tierra}}/\\cos\\theta$.',
      { unit: 'µT', mistakes: { sin: function (v) { return v.bt / Math.sin(v.th / DEG); }, mul: function (v) { return v.bt * Math.cos(v.th / DEG); } }, feedback: [{ when: 'mul', say: 'Multiplicaste por el coseno. La Tierra es la componente: divide.' }] },
      function (v, LM) { var t = Math.tan(v.th / DEG); return perp(LM, v.bt * t, v.bt).mag; }),
    C('su-no-sumar', 'suma', 1, 'Dos campos magnéticos perpendiculares de 3 mT y 4 mT, ¿pueden dar un campo total de 7 mT?', 'No: el total es 5 mT',
      [['Sí: las magnitudes siempre se suman', 'Solo se suman si apuntan en la misma dirección.'], ['No: el total es 1 mT', 'Eso sería si apuntaran en sentidos opuestos.'], ['Sí, si están en un imán', 'Siempre se suman vectorialmente.']],
      'Perpendiculares: $\\sqrt{3^2 + 4^2} = 5$.'),
    C('su-igual', 'suma', 2, 'Una brújula se desvía 45° del norte por un imán perpendicular al campo de la Tierra. Esto significa que el campo del imán, ahí, es…', 'igual al de la Tierra',
      [['el doble del de la Tierra', 'El doble daría unos 63°.'], ['la mitad del de la Tierra', 'La mitad daría unos 27°.'], ['cero', 'Con cero no habría desviación.']],
      '$\\tan 45^\\circ = 1$.'),
    C('su-dominio', 'suma', 2, 'Una brújula está tan cerca de un imán fuerte que su campo es mil veces el de la Tierra. La aguja apunta…', 'casi exactamente en la dirección del campo del imán',
      [['hacia el norte geográfico', 'El campo de la Tierra es despreciable ahí.'], ['en la dirección opuesta al imán', 'Se alinea con el campo del imán.'], ['perpendicular al campo del imán', 'Se alinea con el campo total, que casi es el del imán.']],
      'El campo total es casi el del imán.'),
    C('su-final', 'suma', 3, 'Un imán produce en una brújula un campo hacia el este que es tres veces el de la Tierra (hacia el norte). La aguja apunta…', 'al noreste, pero más cerca del este que del norte',
      [['al noreste, justo en medio', 'Eso ocurriría con campos iguales.'], ['al noreste, más cerca del norte', 'El imán es mayor, así que domina.'], ['directamente al este', 'La Tierra aún tiene una pequeña contribución.']],
      '$\\tan\\theta = 3$, de modo que $\\theta \\approx 71.6^\\circ$ desde el norte.'),
    C('su-eje', 'suma', 2, 'Una brújula está sobre el eje de un imán de barra, del lado del polo N, en un cuarto sin la Tierra. El campo en ese punto…', 'es paralelo al eje y se aleja del imán',
      [['es perpendicular al eje', 'Sobre el eje el campo es paralelo al eje.'], ['es cero', 'El campo es no nulo.'], ['apunta hacia el imán', 'Del lado del N, las líneas se alejan del imán.']],
      'Cerca del polo N, $\\vec B$ sale del imán.'),
    C('su-media', 'suma', 3, 'Una brújula está en la mediatriz de un imán de barra que apunta al norte (de S a N), y la Tierra también aporta un campo hacia el norte. El campo del imán en ese punto apunta al sur. La aguja…', 'apunta al norte si el campo de la Tierra es mayor que el del imán, y al sur si es menor',
      [['siempre apunta al norte', 'Si el imán es más fuerte que la Tierra, domina el sur.'], ['siempre apunta al sur', 'Si la Tierra es más fuerte, domina el norte.'], ['gira sin detenerse', 'La suma es un vector bien definido; si las magnitudes son iguales, es cero.']],
      'Los campos son colineales y opuestos: se restan.')
    ,
    /* ======================= Más preguntas ======================= */
    C('po-fuerza-dist', 'polos', 2, 'Dos imanes se atraen. Si los separas más, la fuerza entre ellos…', 'disminuye, porque el campo de cada uno es más débil donde está el otro',
      [['aumenta, porque tienen más espacio para atraerse', 'La fuerza baja con la distancia.'], ['no cambia, porque depende solo de los polos', 'Depende de la distancia: el campo se debilita al alejarse.'], ['se vuelve repulsión', 'Un cambio de distancia no cambia atracción por repulsión.']],
      'La fuerza magnética disminuye al alejar los imanes.'),
    C('ca-alinea', 'campo', 2, '¿Por qué la aguja de una brújula gira hasta alinearse con $\\vec B$?', 'Porque el campo ejerce sobre el imán de la aguja un torque que la gira hasta alinearla',
      [['Porque el campo la atrae como a un clip de hierro', 'Gira porque el campo hace un torque sobre sus polos; no es atracción de un clip.'], ['Porque la gravedad la jala hacia el norte', 'La gravedad no tiene que ver con la dirección en que se alinea.'], ['Porque la aguja tiene carga eléctrica', 'La aguja es un imán, no una carga.']],
      'En el campo, el polo N de la aguja es empujado en el sentido de $\\vec B$ y el S en el opuesto: eso gira la aguja.'),
    C('li-sin-flecha', 'lineas', 2, 'Un dibujo de las líneas de un imán perdió las flechas. ¿Cómo puedes recuperar su sentido si conoces los polos?', 'Afuera del imán van del polo N al polo S',
      [['Afuera van del polo S al polo N', 'Afuera, las líneas salen del N y entran por el S.'], ['Es imposible: el sentido es arbitrario', 'El sentido está fijado por la convención y la dirección de la aguja.'], ['Van siempre hacia la derecha', 'Dependen de la posición de los polos.']],
      'Convención: salen del N y entran por el S.'),
    C('ca-neutro-brujula', 'campo', 3, 'Entre dos imanes iguales con polos N enfrentados, en el punto medio el campo de los imanes es cero. Si pones ahí una brújula, la aguja…', 'apunta al norte geográfico, porque solo actúa el campo de la Tierra',
      [['queda sin orientación y gira sin parar', 'La Tierra sigue aportando un campo: la aguja se alinea con él.'], ['apunta hacia uno de los imanes', 'Los imanes no aportan campo ahí.'], ['apunta al sur', 'Apunta al norte.']],
      'Si $\\vec B_{\\text{imanes}} = 0$, el campo total es el de la Tierra.'),
    N('ca-comp-y', 'campo', 2, { By: [2, 9, 1], al: [10, 80, 10] },
      function (v) { return 'Un campo de $' + v.By + '\\ \\text{mT}$ forma $' + v.al + '^\\circ$ con el este, hacia el norte (ángulo medido desde el este). ¿Cuánto vale su componente hacia el <strong>norte</strong>, en mT?'; },
      function (v) { return v.By * Math.sin(v.al / DEG); }, 'Medido desde el este, la componente norte es $B\\sin\\alpha$.',
      { unit: 'mT', mistakes: { cos: function (v) { return v.By * Math.cos(v.al / DEG); } }, feedback: [{ when: 'cos', say: 'Esa es la componente este. Con el ángulo medido desde el este, la norte lleva el seno.' }] },
      function (v, LM) { return MG(LM).combine([{ mag: v.By, bearing: 90 - v.al }]).north; }),
    N('su-perp-iguales', 'suma', 2, { b: [10, 90, 10] },
      function (v) { return 'Dos imanes idénticos dan cada uno $' + v.b + '\\ \\mu\\text{T}$ sobre una brújula, en direcciones perpendiculares. ¿Cuánto vale el campo total, en $\\mu\\text{T}$?'; },
      function (v) { return v.b * Math.SQRT2; }, 'Perpendiculares e iguales: $|\\vec B| = \\sqrt{2}\\,b$.',
      { unit: 'µT', mistakes: { sum: function (v) { return 2 * v.b; } }, feedback: [{ when: 'sum', say: 'Sumaste magnitudes; son perpendiculares: $\\sqrt{b^2 + b^2}$.' }] },
      function (v, LM) { return perp(LM, v.b, v.b).mag; }),
    N('su-cancel', 'suma', 3, { a: [60, 150, 10] },
      function (v) { return 'Un imán da $' + v.a + '\\ \\mu\\text{T}$ hacia el este en una brújula y la Tierra $50\\ \\mu\\text{T}$ hacia el norte. Colocas un segundo imán que aporta un campo hacia el norte, de modo que la aguja apunte exactamente al noreste (45°). ¿Cuánto debe aportar el segundo imán, en $\\mu\\text{T}$?'; },
      function (v) { return v.a - 50; }, 'A 45°, la componente norte total debe ser igual a la del este: $50 + x = a$.',
      { unit: 'µT', mistakes: { add: function (v) { return v.a + 50; }, same: function (v) { return v.a; } }, feedback: [{ when: 'same', say: 'La Tierra ya aporta 50 µT al norte; el segundo imán solo debe completar lo que falta.' }] },
      function (v, LM) { var c = MG(LM).combine([{ mag: v.a, bearing: 90 }, { mag: 50, bearing: 0 }]); return c.east - c.north; }),
    N('un-mezcla2', 'unidades', 3, { a: [0.1, 0.5, 0.1] },
      function (v) { return 'Un imán da $' + fx(v.a, 1) + '\\ \\text{mT}$ hacia el este en una brújula y la Tierra $0.50\\ \\text{G}$ hacia el norte. ¿A cuántos grados del norte hacia el este apunta la aguja?'; },
      function (v) { return Math.atan(v.a * 1000 / 50) * DEG; }, 'Pasa los dos a $\\mu\\text{T}$: $0.50\\ \\text{G} = 50\\ \\mu\\text{T}$ y $1\\ \\text{mT} = 1000\\ \\mu\\text{T}$.',
      { unit: '°', mistakes: { noConv: function (v) { return Math.atan(v.a / 0.5) * DEG; }, tenG: function (v) { return Math.atan(v.a * 10 / 50) * DEG; } }, feedback: [{ when: 'noConv', say: 'Mezclaste mT con G. Pasa los dos a la misma unidad.' }] },
      function (v, LM) { var M = MG(LM); return M.combine([{ mag: M.convert(v.a, 'mT', 'uT'), bearing: 90 }, { mag: M.convert(0.5, 'G', 'uT'), bearing: 0 }]).bearing; })
  ];

  K.register({
    'f3.S01.polos': 'Polos y fuerza entre imanes',
    'f3.S01.campo': 'El campo B y la brújula',
    'f3.S01.lineas': 'Líneas de campo',
    'f3.S01.tierra': 'El campo de la Tierra',
    'f3.S01.unidades': 'Unidades y órdenes de magnitud',
    'f3.S01.suma': 'Suma de campos'
  }, Q);
})();
